// crc32: the CRC-32 (IEEE 802.3) of 8 MiB of generated bytes, table-driven.
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

int main(void) {
    const int64_t n = 1 << 23;
    uint8_t *data = malloc(n);
    for (int64_t i = 0; i < n; i++) data[i] = (uint8_t)((i * 2654435761LL >> 13) & 255);
    uint32_t t[256];
    for (uint32_t k = 0; k < 256; k++) {
        uint32_t c = k;
        for (int j = 0; j < 8; j++) c = c & 1 ? 0xEDB88320u ^ (c >> 1) : c >> 1;
        t[k] = c;
    }
    uint32_t crc = 0xFFFFFFFFu;
    for (int64_t i = 0; i < n; i++) crc = t[(crc ^ data[i]) & 255] ^ (crc >> 8);
    printf("%u\n", crc ^ 0xFFFFFFFFu);
    free(data);
    return 0;
}
